/**
 * Verifies that a webhook request really came from Memberstack, using the Svix signature
 * headers. Returns `true` on success and throws an `Error` on any failure, so wrap it in
 * try/catch and answer 400 when it throws.
 *
 * Header keys are matched in any case, so you can pass Node's `req.headers` (lowercase)
 * straight through. Since 1.8.0; earlier versions only read the UPPERCASE keys
 * (`SVIX-ID`, `SVIX-TIMESTAMP`, `SVIX-SIGNATURE`), which still work.
 *
 * @param params - `{ headers, secret, payload, tolerance? }`
 * @param params.headers - An object holding the three Svix headers (any key case)
 * @param params.secret - Your webhook signing secret from the Memberstack dashboard
 * @param params.payload - The parsed JSON body of the request
 * @param params.tolerance - Max age of the request in seconds. Defaults to 300.
 * @returns `true` when the signature and timestamp check out
 *
 * @example Express handler
 * ```typescript
 * app.post('/webhooks/memberstack', express.json(), (req, res) => {
 *   try {
 *     memberstack.verifyWebhookSignature({
 *       headers: req.headers,
 *       secret: process.env.MEMBERSTACK_WEBHOOK_SECRET,
 *       payload: req.body
 *     });
 *   } catch {
 *     return res.status(400).send('Invalid signature');
 *   }
 *   res.sendStatus(200);
 * });
 * ```
 */
export declare const verifyWebhookSignature: ({ headers, secret, payload, tolerance }: {
    headers: object;
    secret: string;
    payload: object;
    tolerance?: number;
}) => boolean;
/**
 * Verifies a legacy `ms-signature` webhook header. Returns `true` on success and throws
 * an `Error` on failure.
 *
 * @deprecated Memberstack webhooks now use Svix headers. Use `verifyWebhookSignature`
 *   instead. This method will be removed in a future major version.
 * @param params - `{ signatureHeader, secret, payload, tolerance? }`
 * @param params.signatureHeader - The raw `ms-signature` header value (`t=... s=...`)
 * @param params.secret - Your webhook signing secret
 * @param params.payload - The parsed JSON body of the request
 * @param params.tolerance - Max age of the request in seconds. Defaults to 300.
 * @returns `true` when the signature and timestamp check out
 *
 * @example
 * ```typescript
 * memberstack.verifySignature({
 *   signatureHeader: req.headers['ms-signature'],
 *   secret: process.env.MEMBERSTACK_WEBHOOK_SECRET,
 *   payload: req.body
 * });
 * ```
 */
export declare const verifySignature: ({ signatureHeader, secret, payload, tolerance }: {
    signatureHeader: string;
    secret: string;
    payload: object;
    tolerance?: number;
}) => boolean;
